// Types for @xoong/core/syntax: the names of xoong's declarative HTML syntax (what `xoong check` validates against).

/** Attributes understood inside `<xo-view>`. */
export const XO_ATTRIBUTES: string[];
/** Custom elements shipped by xoong. */
export const XO_ELEMENTS: string[];
/** Attributes that come with @xoong/ui (the admin set). */
export const XO_UI_ATTRIBUTES: string[];
/** Elements that come with @xoong/ui. */
export const XO_UI_ELEMENTS: string[];
/** Attributes of @xoong/controls and @xoong/richtext. */
export const XO_CONTROL_ATTRIBUTES: string[];
/** Elements of @xoong/controls and @xoong/richtext. */
export const XO_CONTROL_ELEMENTS: string[];
